const crypto = require("node:crypto");
const fs = require("node:fs");
const path = require("node:path");
const { spawnSync } = require("node:child_process");
const { path7za } = require("7zip-bin");
const { assertNonSystemDrive } = require("../src/jarvis/main/SpeakerModelManifest");
const { MODEL_PACK_VERSION, verifyAiModelPack } = require("../src/jarvis/main/AiModelPackManifest");

const APP_ROOT = path.resolve(__dirname, "..");
const DEFAULT_DIST_ROOT = path.join(APP_ROOT, "dist");

function modelArtifactNames(packVersion) {
  if (
    typeof packVersion !== "string" ||
    !/^jarvis-ai-model-pack-[0-9A-Za-z._-]+$/u.test(packVersion)
  ) {
    throw new TypeError("packVersion is invalid");
  }
  const displayVersion = packVersion.slice("jarvis-ai-model-pack-".length);
  return Object.freeze({
    archiveName: `Jarvis AI Model Pack ${displayVersion}.7z`,
    checksumName: `Jarvis AI Model Pack ${displayVersion}.7z.sha512`,
    descriptorName: `Jarvis AI Model Pack ${displayVersion}.release.json`,
  });
}

function renderNsisInclude({ archiveName, sha512 }) {
  if (
    typeof archiveName !== "string" ||
    archiveName.length === 0 ||
    archiveName.length > 180 ||
    !/^[0-9A-Za-z ._-]+\.7z$/u.test(archiveName)
  ) {
    throw new TypeError("archive name is invalid");
  }
  if (typeof sha512 !== "string" || !/^[0-9a-f]{128}$/u.test(sha512)) {
    throw new TypeError("SHA-512 digest is invalid");
  }
  return [
    "; Generated by scripts/build-windows-model-bundle.js. Do not edit.",
    `!define JARVIS_MODEL_ARCHIVE_NAME "${archiveName}"`,
    `!define JARVIS_MODEL_ARCHIVE_SHA512 "${sha512.toUpperCase()}"`,
    "",
  ].join("\r\n");
}

function createArchiveInvocation({
  sevenZipPath,
  modelRoot,
  archivePath,
  listFilePath,
  tempRoot,
  env = process.env,
}) {
  for (const [label, value] of Object.entries({
    sevenZipPath,
    modelRoot,
    archivePath,
    listFilePath,
    tempRoot,
  })) {
    if (typeof value !== "string" || !path.isAbsolute(value)) {
      throw new TypeError(`${label} must be absolute`);
    }
  }
  const safeTemp = path.resolve(tempRoot);
  return Object.freeze({
    command: path.resolve(sevenZipPath),
    args: [
      "a",
      "-t7z",
      "-mx=5",
      "-mmt=on",
      "-bd",
      "-y",
      "-scsUTF-8",
      path.resolve(archivePath),
      `@${path.resolve(listFilePath)}`,
    ],
    options: {
      cwd: path.resolve(modelRoot),
      env: { ...env, TEMP: safeTemp, TMP: safeTemp },
      shell: false,
      stdio: "inherit",
      windowsHide: true,
    },
  });
}

async function hashFile(filePath, algorithm = "sha512") {
  const hash = crypto.createHash(algorithm);
  await new Promise((resolve, reject) => {
    const input = fs.createReadStream(filePath);
    input.on("data", (chunk) => hash.update(chunk));
    input.on("error", reject);
    input.on("end", resolve);
  });
  return hash.digest("hex");
}

async function readDescriptor(filePath, fsImpl) {
  try {
    return JSON.parse(await fsImpl.readFile(filePath, "utf8"));
  } catch (error) {
    if (error?.code === "ENOENT" || error instanceof SyntaxError) return null;
    throw error;
  }
}

async function linkOrCopy(source, target, fsImpl) {
  await fsImpl.rm(target, { force: true });
  try {
    await fsImpl.link(source, target);
  } catch (error) {
    if (!new Set(["EXDEV", "EPERM", "EACCES", "ENOSYS"]).has(error?.code)) throw error;
    await fsImpl.copyFile(source, target);
  }
}

async function buildWindowsModelBundle({
  appRoot = APP_ROOT,
  modelRoot = path.join(appRoot, "resources", "ai-model-pack", "prebuilt"),
  componentRoot = path.join(appRoot, "release-components"),
  tempRoot = path.join(appRoot, "tmp", "model-bundle"),
  nsisIncludePath = path.join(appRoot, "resources", "nsis", "model-pack-release.generated.nsh"),
  sevenZipPath = path7za,
  systemDrive,
  env = process.env,
  fsImpl = fs.promises,
  spawnSyncImpl = spawnSync,
  verifyModelPackImpl = verifyAiModelPack,
  hashFileImpl = hashFile,
} = {}) {
  const safeComponentRoot = assertNonSystemDrive(path.resolve(componentRoot), { systemDrive });
  const safeTempRoot = assertNonSystemDrive(path.resolve(tempRoot), { systemDrive });
  const safeIncludePath = path.resolve(nsisIncludePath);
  const verified = await verifyModelPackImpl({ root: path.resolve(modelRoot), systemDrive });
  const names = modelArtifactNames(verified.manifest.packVersion);
  const archivePath = path.join(safeComponentRoot, names.archiveName);
  const checksumPath = path.join(safeComponentRoot, names.checksumName);
  const descriptorPath = path.join(safeComponentRoot, names.descriptorName);
  await fsImpl.mkdir(safeComponentRoot, { recursive: true });
  await fsImpl.mkdir(safeTempRoot, { recursive: true });

  let descriptor = await readDescriptor(descriptorPath, fsImpl);
  let archiveStat = null;
  try {
    archiveStat = await fsImpl.stat(archivePath);
  } catch (error) {
    if (error?.code !== "ENOENT") throw error;
  }
  let reused = false;
  let sha512;
  if (
    descriptor?.schemaVersion === 2 &&
    descriptor.packVersion === verified.manifest.packVersion &&
    descriptor.manifestSha256 === verified.manifestSha256 &&
    descriptor.archiveName === names.archiveName &&
    Number.isSafeInteger(descriptor.bytes) &&
    descriptor.bytes > 0 &&
    archiveStat?.isFile() &&
    archiveStat.size === descriptor.bytes &&
    /^[0-9a-f]{128}$/u.test(descriptor.sha512 ?? "")
  ) {
    sha512 = await hashFileImpl(archivePath, "sha512");
    reused = sha512 === descriptor.sha512;
  }

  if (!reused) {
    const temporaryArchive = path.join(
      safeTempRoot,
      `.jarvis-model-pack-${crypto.randomUUID()}.7z`
    );
    const listFilePath = path.join(safeTempRoot, `.jarvis-model-pack-${crypto.randomUUID()}.txt`);
    try {
      const archiveEntries = [
        "manifest.json",
        ...verified.manifest.files.map((entry) => entry.path),
      ];
      if (archiveEntries.some((entry) => /[\r\n]/u.test(entry))) {
        throw new Error("model manifest contains an unsupported archive path");
      }
      await fsImpl.writeFile(listFilePath, `${archiveEntries.join("\n")}\n`, "utf8");
      const invocation = createArchiveInvocation({
        sevenZipPath,
        modelRoot: verified.root,
        archivePath: temporaryArchive,
        listFilePath,
        tempRoot: safeTempRoot,
        env,
      });
      const result = spawnSyncImpl(invocation.command, invocation.args, invocation.options);
      if (result.error || result.status !== 0) throw new Error("model component archive failed");
      const temporaryStat = await fsImpl.stat(temporaryArchive);
      if (!temporaryStat.isFile() || temporaryStat.size <= 0) {
        throw new Error("model component archive is empty");
      }
      sha512 = await hashFileImpl(temporaryArchive, "sha512");
      await fsImpl.rm(archivePath, { force: true });
      await fsImpl.rename(temporaryArchive, archivePath);
      descriptor = {
        schemaVersion: 2,
        packVersion: verified.manifest.packVersion,
        manifestSha256: verified.manifestSha256,
        archiveName: names.archiveName,
        bytes: temporaryStat.size,
        sha512,
      };
    } finally {
      await fsImpl.rm(temporaryArchive, { force: true }).catch(() => {});
      await fsImpl.rm(listFilePath, { force: true }).catch(() => {});
    }
  }

  if (!descriptor || !sha512) throw new Error("model component descriptor is unavailable");
  const descriptorText = `${JSON.stringify(descriptor, null, 2)}\n`;
  await fsImpl.writeFile(checksumPath, `${sha512}  ${names.archiveName}\n`, "utf8");
  await fsImpl.writeFile(descriptorPath, descriptorText, "utf8");
  await fsImpl.mkdir(path.dirname(safeIncludePath), { recursive: true });
  await fsImpl.writeFile(
    safeIncludePath,
    renderNsisInclude({ archiveName: names.archiveName, sha512 }),
    "utf8"
  );
  return Object.freeze({
    ...names,
    archivePath,
    checksumPath,
    descriptorPath,
    nsisIncludePath: safeIncludePath,
    bytes: descriptor.bytes,
    sha512,
    reused,
  });
}

async function publishWindowsModelBundle({
  bundle,
  distRoot = DEFAULT_DIST_ROOT,
  systemDrive,
  fsImpl = fs.promises,
} = {}) {
  if (!bundle || typeof bundle !== "object") throw new TypeError("bundle is required");
  const safeDistRoot = assertNonSystemDrive(path.resolve(distRoot), { systemDrive });
  await fsImpl.mkdir(safeDistRoot, { recursive: true });
  for (const [sourceKey, nameKey] of [
    ["archivePath", "archiveName"],
    ["checksumPath", "checksumName"],
    ["descriptorPath", "descriptorName"],
  ]) {
    await linkOrCopy(bundle[sourceKey], path.join(safeDistRoot, bundle[nameKey]), fsImpl);
  }
  return Object.freeze({
    distRoot: safeDistRoot,
    archivePath: path.join(safeDistRoot, bundle.archiveName),
  });
}

async function loadCachedWindowsModelBundle({
  appRoot = APP_ROOT,
  componentRoot = path.join(appRoot, "release-components"),
  packVersion = MODEL_PACK_VERSION,
  systemDrive,
  fsImpl = fs.promises,
  hashFileImpl = hashFile,
} = {}) {
  const safeComponentRoot = assertNonSystemDrive(path.resolve(componentRoot), { systemDrive });
  const names = modelArtifactNames(packVersion);
  const archivePath = path.join(safeComponentRoot, names.archiveName);
  const checksumPath = path.join(safeComponentRoot, names.checksumName);
  const descriptorPath = path.join(safeComponentRoot, names.descriptorName);
  const descriptor = await readDescriptor(descriptorPath, fsImpl);
  const archiveStat = await fsImpl.stat(archivePath);
  if (
    descriptor?.schemaVersion !== 2 ||
    descriptor.packVersion !== packVersion ||
    descriptor.archiveName !== names.archiveName ||
    descriptor.bytes !== archiveStat.size ||
    !/^[0-9a-f]{128}$/u.test(descriptor.sha512 ?? "")
  ) {
    throw new Error("cached model component descriptor is invalid");
  }
  const sha512 = await hashFileImpl(archivePath, "sha512");
  if (sha512 !== descriptor.sha512) throw new Error("cached model component checksum is invalid");
  return Object.freeze({
    ...names,
    archivePath,
    checksumPath,
    descriptorPath,
    bytes: descriptor.bytes,
    sha512,
    reused: true,
  });
}

async function main() {
  const publishOnly = process.argv.includes("--publish-only");
  const bundle = publishOnly
    ? await loadCachedWindowsModelBundle()
    : await buildWindowsModelBundle();
  if (publishOnly || process.argv.includes("--publish-to-dist")) {
    await publishWindowsModelBundle({ bundle });
  }
  process.stdout.write(
    `[jarvis-model-pack] ${bundle.reused ? "reused" : "built"} ${bundle.archiveName} (${bundle.bytes} bytes)\n`
  );
}

if (require.main === module) {
  main().catch((error) => {
    process.stderr.write(`[jarvis-model-pack] ${error?.message || "build failed"}\n`);
    process.exitCode = 1;
  });
}

module.exports = {
  buildWindowsModelBundle,
  createArchiveInvocation,
  hashFile,
  loadCachedWindowsModelBundle,
  modelArtifactNames,
  publishWindowsModelBundle,
  renderNsisInclude,
};
